# Excel to CSV Converter using Qt5

Here's a complete Qt5 application that converts Excel files to CSV:

## Project File (CMakeLists.txt)

```cmake
cmake_minimum_required(VERSION 3.16)
project(ExcelToCSVConverter)

set(CMAKE_CXX_STANDARD 17)
set(CMAKE_AUTOMOC ON)
set(CMAKE_AUTORCC ON)
set(CMAKE_INCLUDE_CURRENT_DIR ON)

find_package(Qt5 COMPONENTS Core Gui Widgets REQUIRED)

add_executable(ExcelToCSVConverter
    main.cpp
    mainwindow.h
    mainwindow.cpp
    converter.h
    converter.cpp
)

target_link_libraries(ExcelToCSVConverter Qt5::Core Qt5::Gui Qt5::Widgets)
```

## Header Files

### mainwindow.h

```cpp
#ifndef MAINWINDOW_H
#define MAINWINDOW_H

#include <QMainWindow>
#include <QPushButton>
#include <QLabel>
#include <QTextEdit>
#include "converter.h"

class MainWindow : public QMainWindow {
    Q_OBJECT

public:
    MainWindow(QWidget *parent = nullptr);
    ~MainWindow();

private slots:
    void onSelectDirectory();
    void onConversionProgress(const QString &message);
    void onConversionFinished(bool success, const QString &message);

private:
    void setupUI();

    QPushButton *selectDirButton;
    QPushButton *convertButton;
    QLabel *selectedPathLabel;
    QTextEdit *logTextEdit;
    ExcelConverter *converter;
    QString selectedDirectory;
};

#endif // MAINWINDOW_H
```

### converter.h

```cpp
#ifndef CONVERTER_H
#define CONVERTER_H

#include <QObject>
#include <QString>
#include <QStringList>

class ExcelConverter : public QObject {
    Q_OBJECT

public:
    explicit ExcelConverter(QObject *parent = nullptr);

    void convertExcelFilesInDirectory(const QString &directoryPath);

signals:
    void progress(const QString &message);
    void finished(bool success, const QString &message);

private:
    QStringList findExcelFiles(const QString &directoryPath);
    bool convertExcelToCSV(const QString &excelFilePath, const QString &outputDirectory);
};

#endif // CONVERTER_H
```

## Implementation Files

### mainwindow.cpp

```cpp
#include "mainwindow.h"
#include <QVBoxLayout>
#include <QHBoxLayout>
#include <QFileDialog>
#include <QMessageBox>

MainWindow::MainWindow(QWidget *parent)
    : QMainWindow(parent), converter(nullptr) {
    setWindowTitle("Excel to CSV Converter");
    setGeometry(100, 100, 700, 600);

    setupUI();

    converter = new ExcelConverter(this);
    connect(converter, &ExcelConverter::progress, this, &MainWindow::onConversionProgress);
    connect(converter, &ExcelConverter::finished, this, &MainWindow::onConversionFinished);
}

MainWindow::~MainWindow() {
}

void MainWindow::setupUI() {
    QWidget *centralWidget = new QWidget(this);
    setCentralWidget(centralWidget);

    QVBoxLayout *mainLayout = new QVBoxLayout(centralWidget);

    // Directory selection section
    QHBoxLayout *dirLayout = new QHBoxLayout();
    selectDirButton = new QPushButton("Select Directory", this);
    connect(selectDirButton, &QPushButton::clicked, this, &MainWindow::onSelectDirectory);
    dirLayout->addWidget(new QLabel("Selected Directory:", this));
    dirLayout->addStretch();
    dirLayout->addWidget(selectDirButton);

    mainLayout->addLayout(dirLayout);

    selectedPathLabel = new QLabel("No directory selected", this);
    selectedPathLabel->setStyleSheet("background-color: #f0f0f0; padding: 5px; border-radius: 3px;");
    mainLayout->addWidget(selectedPathLabel);

    // Convert button
    convertButton = new QPushButton("Convert Excel Files to CSV", this);
    convertButton->setEnabled(false);
    convertButton->setStyleSheet("QPushButton { padding: 8px; font-weight: bold; }");
    connect(convertButton, &QPushButton::clicked, this, [this]() {
        if (!selectedDirectory.isEmpty()) {
            convertButton->setEnabled(false);
            converter->convertExcelFilesInDirectory(selectedDirectory);
        }
    });
    mainLayout->addWidget(convertButton);

    // Log section
    QLabel *logLabel = new QLabel("Conversion Log:", this);
    mainLayout->addWidget(logLabel);

    logTextEdit = new QTextEdit(this);
    logTextEdit->setReadOnly(true);
    logTextEdit->setStyleSheet("background-color: #2b2b2b; color: #00ff00; font-family: Courier;");
    mainLayout->addWidget(logTextEdit);

    mainLayout->setContentsMargins(15, 15, 15, 15);
    mainLayout->setSpacing(10);
}

void MainWindow::onSelectDirectory() {
    QString directory = QFileDialog::getExistingDirectory(
        this,
        "Select Directory Containing Excel Files",
        QDir::homePath(),
        QFileDialog::ShowDirsOnly | QFileDialog::DontResolveSymlinks
    );

    if (!directory.isEmpty()) {
        selectedDirectory = directory;
        selectedPathLabel->setText(directory);
        convertButton->setEnabled(true);
        logTextEdit->clear();
    }
}

void MainWindow::onConversionProgress(const QString &message) {
    logTextEdit->append(message);
}

void MainWindow::onConversionFinished(bool success, const QString &message) {
    convertButton->setEnabled(!selectedDirectory.isEmpty());

    if (success) {
        logTextEdit->append("\n✓ Conversion completed successfully!");
        QMessageBox::information(this, "Success", message);
    } else {
        logTextEdit->append("\n✗ Conversion failed!");
        QMessageBox::warning(this, "Error", message);
    }
}
```

### converter.cpp

```cpp
#include "converter.h"
#include <QDir>
#include <QFile>
#include <QFileInfo>
#include <QXmlStreamReader>
#include <QDebug>
#include <QStandardPaths>
#include <QDateTime>

ExcelConverter::ExcelConverter(QObject *parent)
    : QObject(parent) {
}

void ExcelConverter::convertExcelFilesInDirectory(const QString &directoryPath) {
    QDir directory(directoryPath);

    if (!directory.exists()) {
        emit finished(false, "Directory does not exist: " + directoryPath);
        return;
    }

    // Find all Excel files
    QStringList excelFiles = findExcelFiles(directoryPath);

    if (excelFiles.isEmpty()) {
        emit progress("No Excel files found in directory.");
        emit finished(false, "No Excel files found.");
        return;
    }

    emit progress("Found " + QString::number(excelFiles.count()) + " Excel file(s).");

    // Create output directory
    QString outputDir = directoryPath + "/CSV_Output";
    QDir().mkpath(outputDir);

    if (!QDir(outputDir).exists()) {
        emit finished(false, "Could not create output directory.");
        return;
    }

    emit progress("Output directory created: " + outputDir);
    emit progress(""); // Blank line

    // Convert each file
    int successCount = 0;
    for (const QString &excelFile : excelFiles) {
        emit progress("Processing: " + QFileInfo(excelFile).fileName());

        if (convertExcelToCSV(excelFile, outputDir)) {
            successCount++;
            emit progress("  ✓ Successfully converted");
        } else {
            emit progress("  ✗ Failed to convert");
        }
    }

    emit progress(""); // Blank line
    QString resultMessage = QString("Converted %1 out of %2 files successfully.")
        .arg(successCount).arg(excelFiles.count());

    emit progress(resultMessage);
    emit finished(successCount > 0, resultMessage);
}

QStringList ExcelConverter::findExcelFiles(const QString &directoryPath) {
    QDir directory(directoryPath);
    QStringList filters;
    filters << "*.xlsx" << "*.xls" << "*.XLSX" << "*.XLS";

    directory.setNameFilters(filters);
    directory.setFilter(QDir::Files | QDir::NoSymLinks);

    return directory.entryList();
}

bool ExcelConverter::convertExcelToCSV(const QString &excelFilePath, const QString &outputDirectory) {
    QFileInfo fileInfo(excelFilePath);
    QString csvFileName = fileInfo.baseName() + ".csv";
    QString csvFilePath = outputDirectory + "/" + csvFileName;

    try {
        // Open the Excel file as a zip archive
        QFile excelFile(excelFilePath);
        if (!excelFile.open(QIODevice::ReadOnly)) {
            return false;
        }

        // For .xlsx files (which are zip archives), we need to extract and parse XML
        // For simplicity, this example uses a basic approach
        // In production, you might want to use a library like xlsxio or libxlsx

        // This is a simplified version that works with basic Excel files
        // For more robust conversion, consider using libraries like:
        // - xlsxio
        // - libxlsx
        // - libreoffice command-line tool

        // Using LibreOffice command line as a fallback approach:
        QString command = QString("libreoffice --headless --convert-to csv:%1 --outdir \"%2\" \"%3\"")
            .arg("Text - txt - csv (StarCalc):44,34,76,1,,0,false,true,true,false,false")
            .arg(outputDirectory)
            .arg(excelFilePath);

        int result = system(command.toStdString().c_str());

        if (result == 0) {
            // Rename the output file to match our naming convention
            QString generatedFile = outputDirectory + "/" + fileInfo.baseName() + ".csv";
            return QFile::exists(generatedFile);
        }

        return false;
    } catch (...) {
        return false;
    }
}
```

### main.cpp

```cpp
#include <QApplication>
#include "mainwindow.h"

int main(int argc, char *argv[]) {
    QApplication app(argc, argv);

    MainWindow window;
    window.show();

    return app.exec();
}
```

## Building and Running

### On Linux/macOS:

```bash
mkdir build
cd build
cmake ..
make
./ExcelToCSVConverter
```

### On Windows (with Visual Studio):

```bash
mkdir build
cd build
cmake -G "Visual Studio 16 2019" ..
cmake --build . --config Release
Release\ExcelToCSVConverter.exe
```

## Dependencies

This basic version uses LibreOffice for conversion. For a more robust solution without external dependencies, install a library:

**For advanced Excel parsing without LibreOffice:**

```bash
# Install xlsxio (Ubuntu/Debian)
sudo apt-get install libxlsxio-dev

# Or install xlnt (header-only C++14 library)
# https://github.com/tfussell/xlnt
```

## Features

✅ Simple Qt5 GUI  
✅ Directory selection dialog  
✅ Finds all `.xlsx` and `.xls` files  
✅ Creates output folder automatically  
✅ Converts Excel to CSV  
✅ Real-time conversion log  
✅ Success/failure reporting  

This solution provides a user-friendly interface for batch converting Excel files to CSV format!

